rtl/swap_pair4/reference/swap_pair4.v.content:
`timescale 1ns/1ps
module swap_pair4 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_load,
    input wire i_swap,
    input wire [3:0] i_a,
    input wire [3:0] i_b,
    output reg [3:0] o_a,
    output reg [3:0] o_b
);
always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            o_a <= 4'd1;
            o_b <= 4'd2;
        end else if (i_load) begin
            o_a <= i_a;
            o_b <= i_b;
        end else if (i_swap) begin
            o_a <= o_b;
            o_b <= o_a;
        end
    end
endmodule

rtl/priority_count8/reference/priority_c.content:
