rtl/mod10_counter/reference/mod10_counte.content:
`timescale 1ns/1ps
module mod10_counter (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_enable_level,
    output reg [3:0] o_count,
    output reg o_tick_pulse
);
always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            o_count <= 4'd0;
            o_tick_pulse <= 1'b0;
        end else begin
            o_tick_pulse <= i_enable_level && (o_count == 4'd9);
            if (i_enable_level) begin
                if (o_count == 4'd9)
                    o_count <= 4'd0;
                else
                    o_count <= o_count + 4'd1;
            end
        end
    end
endmodule

