module saturating_count3 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_up,
    input wire i_down,
    output reg [2:0] o_count
);
always @(posedge i_clk_sys) begin
        if (i_rst_sync)
            o_count <= 3'd0;
        else if (i_up && !i_down) begin
            if (o_count != 3'd7)
                o_count <= o_count + 3'd1;
        end else if (i_down && !i_up) begin
            if (o_count != 3'd0)
                o_count <= o_count - 3'd1;
        end
    end
endmodule

