`timescale 1ns/1ps
module tick_every5 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_enable_level,
    output reg o_tick_pulse
);
reg [2:0] count_r;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            count_r <= 3'd0;
            o_tick_pulse <= 1'b0;
        end else begin
            o_tick_pulse <= 1'b0;
            if (i_enable_level) begin
                if (count_r == 3'd4) begin
                    count_r <= 3'd0;
                    o_tick_pulse <= 1'b1;
                end else begin
                    count_r <= count_r + 3'd1;
                end
            end
        end
    end
endmodule

