rtl/armed_fsm/reference/armed_fsm.v.content:
`timescale 1ns/1ps
module armed_fsm (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_start,
    input wire i_trigger,
    input wire i_cancel,
    output wire o_busy_level,
    output wire o_fire_pulse
);
localparam IDLE = 2'd0, ARMED = 2'd1, FIRE = 2'd2;
    reg [1:0] state_r;
    reg [1:0] state_next;
    always @* begin
        state_next = state_r;
        case (state_r)
            IDLE: if (i_start) state_next = ARMED;
            ARMED: begin
                if (i_cancel) state_next = IDLE;
                else if (i_trigger) state_next = FIRE;
            end
            FIRE: state_next = IDLE;
            default: state_next = IDLE;
        endcase
    end
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) state_r <= IDLE;
        else state_r <= state_next;
    end
    assign o_busy_level = (state_r != IDLE);
    assign o_fire_pulse = (state_r == FIRE);
endmodule

