module serial_1011 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_bit_valid,
    input wire i_bit,
    output reg o_hit_pulse
);
reg [2:0] history_r;
    reg [1:0] seen_r;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            history_r <= 3'd0;
            seen_r <= 2'd0;
            o_hit_pulse <= 1'b0;
        end else begin
            o_hit_pulse <= 1'b0;
            if (i_bit_valid) begin
                o_hit_pulse <= (seen_r == 2'd3) &&
                              ({history_r, i_bit} == 4'b1011);
                history_r <= {history_r[1:0], i_bit};
                if (seen_r != 2'd3)
                    seen_r <= seen_r + 2'd1;
            end
        end
    end
endmodule

