module sum_pipeline2 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_valid,
    input wire [7:0] i_a,
    input wire [7:0] i_b,
    output reg o_valid,
    output reg [8:0] o_sum
);
reg valid_r;
    reg [8:0] sum_r;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            valid_r <= 1'b0;
            o_valid <= 1'b0;
            sum_r <= 9'd0;
            o_sum <= 9'd0;
        end else begin
            valid_r <= i_valid;
            o_valid <= valid_r;
            if (i_valid)
                sum_r <= {1'b0, i_a} + {1'b0, i_b};
            if (valid_r)
                o_sum <= sum_r;
        end
    end
endmodule

