rtl/sync_fifo4/reference/sync_fifo4.v.content:
`timescale 1ns/1ps
module sync_fifo4 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_write,
    input wire i_read,
    input wire [7:0] i_data,
    output wire o_empty,
    output wire o_full,
    output reg [2:0] o_count,
    output reg o_read_valid,
    output reg [7:0] o_read_data
);
reg [7:0] mem_r [0:3];
    reg [1:0] write_ptr_r;
    reg [1:0] read_ptr_r;
    wire push;
    wire pop;
    assign o_empty = (o_count == 3'd0);
    assign o_full = (o_count == 3'd4);
    assign push = i_write && !o_full;
    assign pop = i_read && !o_empty;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            write_ptr_r <= 2'd0;
            read_ptr_r <= 2'd0;
            o_count <= 3'd0;
            o_read_valid <= 1'b0;
            o_read_data <= 8'd0;
        end else begin
            o_read_valid <= pop;
            if (push) begin
                mem_r[write_ptr_r] <= i_data;
                write_ptr_r <= write_ptr_r + 2'd1;
            end
            if (pop) begin
                o_read_data <= mem_r[read_ptr_r];
                read_ptr_r <= read_ptr_r + 2'd1;
            end
            case ({push, pop})
                2'b10: o_count <= o_count + 3'd1;
                2'b01: o_count <= o_count - 3'd1;
                default: o_count <= o_count;
            endcase
        end
    end
endmodule

