rtl/gray_counter4/reference/gray_counter.content:
`timescale 1ns/1ps
module gray_counter4 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_enable_level,
    output reg [3:0] o_binary,
    output reg [3:0] o_gray
);
wire [3:0] binary_next;
    assign binary_next = o_binary + 4'd1;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            o_binary <= 4'd0;
            o_gray <= 4'd0;
        end else if (i_enable_level) begin
            o_binary <= binary_next;
            o_gray <= binary_next ^ (binary_next >> 1);
        end
    end
endmodule

