`timescale 1ns/1ps
module read_first_ram4 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_write,
    input wire [1:0] i_write_addr,
    input wire [7:0] i_write_data,
    input wire i_read,
    input wire [1:0] i_read_addr,
    output reg o_read_valid,
    output reg [7:0] o_read_data
);
reg [7:0] mem_r [0:3];
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            o_read_valid <= 1'b0;
            o_read_data <= 8'd0;
        end else begin
            o_read_valid <= i_read;
            if (i_write)
                mem_r[i_write_addr] <= i_write_data;
            if (i_read)
                o_read_data <= mem_r[i_read_addr];
        end
    end
endmodule

rtl/signed_sat_add8/reference/signed_sat.content:
`timescale 1ns/1ps
module signed_sat_add8 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_valid,
    input wire signed [7:0] i_a,
    input wire signed [7:0] i_b,
    output reg o_valid,
    output reg signed [7:0] o_sum
);
wire signed [8:0] full_sum;
    assign full_sum = {i_a[7], i_a} + {i_b[7], i_b};
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            o_valid <= 1'b0;
            o_sum <= 8'sd0;
        end else begin
            o_valid <= i_valid;
            if (i_valid) begin
                if (full_sum > 9'sd127)
                    o_sum <= 8'sd127;
                else if (full_sum < -9'sd128)
                    o_sum <= -8'sd128;
                else
                    o_sum <= full_sum[7:0];
            end
        end
    end
endmodule

