`timescale 1ns/1ps
module max4_pipeline2 (
    input wire i_clk_sys,
    input wire i_rst_sync,
    input wire i_valid,
    input wire [7:0] i_a,
    input wire [7:0] i_b,
    input wire [7:0] i_c,
    input wire [7:0] i_d,
    output reg o_valid,
    output reg [7:0] o_max
);
reg valid_r;
    reg [7:0] max_ab_r;
    reg [7:0] max_cd_r;
    always @(posedge i_clk_sys) begin
        if (i_rst_sync) begin
            valid_r <= 1'b0;
            o_valid <= 1'b0;
            max_ab_r <= 8'd0;
            max_cd_r <= 8'd0;
            o_max <= 8'd0;
        end else begin
            valid_r <= i_valid;
            o_valid <= valid_r;
            if (i_valid) begin
                max_ab_r <= (i_a > i_b) ? i_a : i_b;
                max_cd_r <= (i_c > i_d) ? i_c : i_d;
            end
            if (valid_r)
                o_max <= (max_ab_r > max_cd_r) ? max_ab_r : max_cd_r;
        end
    end
endmodule
